// Decides whether to alert. The previous overall status lives in workflow static data, which n8n
// saves only for production runs (workflow active, started by the schedule) — not for manual test runs.
const RANK = { ok: 0, warn: 1, fail: 2 };
const settings = $('Settings').first().json;
const res = $input.first().json;
const state = $getWorkflowStaticData('global');
const now = new Date();
const reminderMs = Number(settings.reminderHours || 6) * 3600 * 1000;
const server = settings.serverName || 'PostgreSQL';

// What did /status say? A request error or a non-2xx answer is a fail.
let body = res.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { /* not JSON */ }
}
const code = typeof res.statusCode === 'number' ? res.statusCode : null;
let current;
let problems;
if (code !== null && code >= 200 && code < 300 && body && RANK[body.status] !== undefined) {
  current = body.status;
  problems = (Array.isArray(body.checks) ? body.checks : []).filter((c) => c && c.status !== 'ok');
} else {
  current = 'fail';
  let why;
  if (code !== null) {
    const detail = body && typeof body === 'object' && body.error ? ` (${body.error})` : '';
    why = `the status endpoint answered HTTP ${code}${detail}`;
  } else {
    const err = res.error;
    const msg = (err && (err.message || err.description)) || (typeof err === 'string' ? err : '') || res.message || 'no response';
    why = `request to the status endpoint failed: ${msg}`;
  }
  problems = [{ name: 'status_request', status: 'fail', message: why }];
}

// Alert on a change of overall state, and every reminderHours while it stays at fail.
const previous = RANK[state.lastStatus] !== undefined ? state.lastStatus : null;
let reason = null;
if (previous === null) {
  if (current !== 'ok') reason = 'first-check';
} else if (previous !== current) {
  reason = current === 'ok' ? 'recovered' : RANK[current] > RANK[previous] ? 'worse' : 'better';
} else if (current === 'fail' && now.getTime() - new Date(state.lastAlertAt || 0).getTime() >= reminderMs) {
  reason = 'reminder';
}

if (previous !== current) state.since = now.toISOString();
state.lastStatus = current;
state.lastCheckedAt = now.toISOString();
if (reason) state.lastAlertAt = now.toISOString();

const up = (s) => String(s).toUpperCase();
const failing = problems.filter((p) => p.status === 'fail');
const warning = problems.filter((p) => p.status === 'warn');
const headline = {
  'first-check': up(current),
  worse: `${up(current)} (was ${previous ? up(previous) : '?'})`,
  better: `improved to ${up(current)} (was ${previous ? up(previous) : '?'})`,
  recovered: `RECOVERED (was ${previous ? up(previous) : '?'})`,
  reminder: `still FAIL since ${state.since}`,
}[reason] || up(current);
const counts = [failing.length ? `${failing.length} failing` : '', warning.length ? `${warning.length} warning` : ''].filter(Boolean).join(', ');
const subject = `[${server}] ${headline}${counts ? ` - ${counts}` : ''}`;

const lines = [
  `${server} database health is ${up(current)}${previous && previous !== current ? ` (was ${up(previous)})` : ''}.`,
  `Checked at ${now.toISOString()}; in this state since ${state.since}.`,
  '',
];
const list = (title, items) => {
  if (!items.length) return;
  lines.push(`${title}:`);
  for (const p of items.slice(0, 40)) lines.push(`  - ${p.name}: ${String(p.message || '').slice(0, 500)}`);
  lines.push('');
};
list('Failing', failing);
list('Warnings', warning);
if (!problems.length) lines.push('All checks are ok.', '');
lines.push(`Details: ${settings.statusUrl} (needs the bearer token)`);
if (reason === 'reminder' || current === 'fail') lines.push(`While this stays at FAIL a reminder is sent every ${Number(settings.reminderHours || 6)} h.`);

const text = lines.join('\n');
const chatText = [`*${subject}*`, ...failing.map((p) => `FAIL ${p.name}: ${p.message}`), ...warning.map((p) => `WARN ${p.name}: ${p.message}`)].join('\n');

return [{ json: { alert: Boolean(reason), reason, current, previous, subject, text, chatText } }];
